// Helper — returns the vocabulary block for an industry by slug, with fallback
// to mapped sectors (e.g., bakery / sweets reuse food-processing vocabulary).
export const INDUSTRY_VOCABULARY_FALLBACKS = {
  bakery: 'food-processing',
  sweets: 'food-processing',
  spices: 'food-processing',
  beverages: 'food-processing',
  'non-food-fmcg': 'fmcg',
  engineering: null,
};

export function getIndustryVocabulary(slug) {
  if (INDUSTRY_VOCABULARY[slug]) return INDUSTRY_VOCABULARY[slug];
  const fallback = INDUSTRY_VOCABULARY_FALLBACKS[slug];
  return fallback ? INDUSTRY_VOCABULARY[fallback] : null;
}

